using System;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.UI;
namespace DragonTower.Editor {public static class HudRestoreValidation {
 public static void Run(){try{var go=new GameObject("HUD test",typeof(RectTransform),typeof(Image),typeof(Button));var image=go.GetComponent<Image>();var b=go.GetComponent<Button>();b.targetGraphic=image;AncientUi.Button(b);var menu=go.GetComponentInChildren<AncientStoneSurface>();var pixel=(PixelHudFrame)typeof(BattleView).GetMethod("PixelFrame",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{image,true});if(menu.gameObject.activeSelf||go.GetComponent<AncientButtonFeedback>().enabled||b.transition!=Selectable.Transition.ColorTint)throw new Exception("Menu overlay not removed");foreach(var theme in Resources.LoadAll<ElementHudTheme>("HudThemes")){typeof(BattleView).GetMethod("SetThemeEdge",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{pixel,theme.primaryColor});if(pixel.edge!=theme.primaryColor)throw new Exception("Wrong colour "+theme.element);Debug.Log("HUD_ELEMENT_OK "+theme.element);}UnityEngine.Object.DestroyImmediate(go);Debug.Log("HUD_RESTORE_OK menu removed original theme colours and interaction retained");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}}
